-- Typed request and runner/service state. JSON is confined to validation and output.
pub type StepDefinition = StepDefinition {
  id: String,
  needs: List(String),
  amount: Int,
  failures: Int
}

pub type Checkpoint = AfterBegin | AfterCall

pub type Command
  = Start(String)
  | Tick(Option(Checkpoint))
  | Advance(Int)
  | Observe
  | Crash
  | Restart
  | Cancel(String)

pub type Workflow = Workflow {
  steps: List(StepDefinition),
  commands: List(Command),
  max_attempts: Int,
  retry_delay: Int
}

pub type StepStatus = Pending | Running | Succeeded | Failed | Blocked | Cancelled deriving (Eq)
pub type RunStatus = Active | Completed | RunFailed | Cancelling | RunCancelled deriving (Eq)

pub type StepState = StepState {
  id: String,
  status: StepStatus,
  attempts: Int,
  ready_at: Int
}

pub type RunState = RunState {
  id: String,
  status: RunStatus,
  cancel_requested: Bool,
  steps: List(StepState)
}

pub type ActionKey = ActionKey { run_id: String, step_id: String }
pub type ServiceCall = ServiceCall { kind: String, key: ActionKey, attempt: Int, outcome: String }
pub type Effect = Effect { key: ActionKey, amount: Int }
pub type MockService = MockService { calls: List(ServiceCall), effects: List(Effect) }
pub type ServiceResult = ServiceResult { service: MockService, outcome: String }

pub type Snapshot = Snapshot { now: Int, up: Bool, runs: List(RunState) }
pub type Simulator = Simulator {
  now: Int,
  up: Bool,
  runs: List(RunState),
  service: MockService,
  observations: List(Snapshot)
}

pub type Action = Action { run: RunState, step: StepState, definition: StepDefinition }

pub fn time_limit() : Int = 2147483647

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Json (..)
import Domain (..)
import Runner (snapshot)

fn step_status(status : StepStatus) : String =
  match status of
    Pending => "pending"
    Running => "running"
    Succeeded => "succeeded"
    Failed => "failed"
    Blocked => "blocked"
    Cancelled => "cancelled"

fn run_status(status : RunStatus) : String =
  match status of
    Active => "active"
    Completed => "succeeded"
    RunFailed => "failed"
    Cancelling => "cancelling"
    RunCancelled => "cancelled"

fn step_json(step : StepState) : Json =
  JObj([("id", JStr(step.id)), ("status", JStr(step_status(step.status))),
    ("attempts", JInt(step.attempts)), ("ready_at", JInt(step.ready_at))])

fn run_json(run : RunState) : Json =
  JObj([("id", JStr(run.id)), ("status", JStr(run_status(run.status))),
    ("cancel_requested", JBool(run.cancel_requested)), ("steps", JArr(map(step_json, run.steps)))])

fn snapshot_fields(state : Snapshot) : List((String, Json)) =
  [("now", JInt(state.now)), ("up", JBool(state.up)), ("runs", JArr(map(run_json, state.runs)))]

fn snapshot_json(state : Snapshot) : Json = JObj(snapshot_fields(state))

fn key_json(key : ActionKey) : Json = JArr([JStr(key.run_id), JStr(key.step_id)])

fn call_json(call : ServiceCall) : Json =
  JObj([("kind", JStr(call.kind)), ("key", key_json(call.key)),
    ("attempt", JInt(call.attempt)), ("outcome", JStr(call.outcome))])

fn effect_json(entry : Effect) : Json =
  JObj([("key", key_json(entry.key)), ("amount", JInt(entry.amount))])

pub fn result_json(sim : Simulator) : Json =
  let final_fields = append(snapshot_fields(snapshot(sim)),
    [("calls", JArr(map(call_json, sim.service.calls))), ("effects", JArr(map(effect_json, sim.service.effects)))])
  JObj([("observations", JArr(map(snapshot_json, sim.observations))), ("final", JObj(final_fields))])

pub fn response_json(result : Result(Simulator, String)) : Json =
  match result of
    Ok(sim) => JObj([("ok", JBool(true)), ("result", result_json(sim))])
    Err(code) => JObj([("ok", JBool(false)), ("error", JObj([("code", JStr(code))]))])

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Domain (..)
import Service (..)

pub fn new_simulator() : Simulator =
  Simulator { now = 0, up = true, runs = [], service = new_service(), observations = [] }

pub fn snapshot(sim : Simulator) : Snapshot =
  -- Persistent values make every historical snapshot independent of later updates.
  Snapshot { now = sim.now, up = sim.up, runs = sim.runs }

fn new_step(now : Int, definition : StepDefinition) : StepState =
  StepState { id = definition.id, status = Pending, attempts = 0, ready_at = now }

fn select_step(now : Int, inflight : Bool, run : RunState, states : List(StepState), definitions : List(StepDefinition)) : Option(Action) =
  match (states, definitions) of
    (Cons(step, more_states), Cons(definition, more_definitions)) =>
      let ready =
        if inflight then step.status == Running
        else run.status == Active && step.status == Pending && step.ready_at <= now
          && all(\(dep) -> any(\(s) -> s.id == dep && s.status == Succeeded, run.steps), definition.needs)
      if ready then Some(Action { run = run, step = step, definition = definition })
      else select_step(now, inflight, run, more_states, more_definitions)
    _ => None

fn select_run(now : Int, inflight : Bool, runs : List(RunState), definitions : List(StepDefinition)) : Option(Action) =
  match runs of
    Nil => None
    Cons(run, rest) =>
      match select_step(now, inflight, run, run.steps, definitions) of
        Some(action) => Some(action)
        None => select_run(now, inflight, rest, definitions)

pub fn select_action(sim : Simulator, workflow : Workflow) : Option(Action) =
  -- Resume the oldest in-flight attempt before scanning ready pending work.
  match select_run(sim.now, true, sim.runs, workflow.steps) of
    Some(action) => Some(action)
    None => select_run(sim.now, false, sim.runs, workflow.steps)

fn replace_step(run : RunState, replacement : StepState) : RunState =
  RunState { ..run, steps = map(\(step) -> if step.id == replacement.id then replacement else step, run.steps) }

fn replace_run(sim : Simulator, replacement : RunState) : Simulator =
  Simulator { ..sim, runs = map(\(run) -> if run.id == replacement.id then replacement else run, sim.runs) }

fn block_pending(step : StepState) : StepState =
  if step.status == Pending then StepState { ..step, status = Blocked } else step

fn cancel_pending(step : StepState) : StepState =
  if step.status == Pending then StepState { ..step, status = Cancelled } else step

fn commit_success(sim : Simulator, run : RunState, running : StepState) : Simulator =
  let completed = replace_step(run, StepState { ..running, status = Succeeded })
  let finished =
    if all(\(step) -> step.status == Succeeded, completed.steps) then
      RunState { ..completed, status = Completed }
    else completed
  replace_run(sim, finished)

pub fn tick(sim : Simulator, workflow : Workflow, checkpoint : Option(Checkpoint)) : Result(Simulator, String) =
  match select_action(sim, workflow) of
    None => Ok(sim)
    Some(action) =>
      let running =
        if action.step.status == Pending then
          StepState { ..action.step, status = Running, attempts = action.step.attempts + 1 }
        else action.step
      let begun_run = replace_step(action.run, running)
      let begun = replace_run(sim, begun_run)
      match checkpoint of
        Some(AfterBegin) => Ok(Simulator { ..begun, up = false })
        _ =>
          let key = ActionKey { run_id = action.run.id, step_id = running.id }
          let response =
            if begun_run.status == Cancelling then lookup(begun.service, key, running.attempts)
            else execute(begun.service, key, action.definition.amount, running.attempts, action.definition.failures)
          let called = Simulator { ..begun, service = response.service }
          match checkpoint of
            Some(AfterCall) => Ok(Simulator { ..called, up = false })
            _ =>
              if begun_run.status == Cancelling then
                let reconciled_status = if response.outcome == "found" then Succeeded else Cancelled
                let reconciled = replace_step(begun_run, StepState { ..running, status = reconciled_status })
                Ok(replace_run(called, RunState { ..reconciled, status = RunCancelled }))
              elif response.outcome == "transient" then
                if running.attempts < workflow.max_attempts then
                  if sim.now + workflow.retry_delay > time_limit() then Err("TIME_OVERFLOW")
                  else
                    let pending = StepState { ..running, status = Pending, ready_at = sim.now + workflow.retry_delay }
                    Ok(replace_run(called, replace_step(begun_run, pending)))
                else
                  let failed = replace_step(begun_run, StepState { ..running, status = Failed })
                  let stopped = RunState { ..failed, status = RunFailed, steps = map(block_pending, failed.steps) }
                  Ok(replace_run(called, stopped))
              else Ok(commit_success(called, begun_run, running))

pub fn apply_command(sim : Simulator, workflow : Workflow, command : Command) : Result(Simulator, String) =
  match command of
    Start(id) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      elif any(\(run) -> run.id == id, sim.runs) then Err("DUPLICATE_RUN")
      else
        let run = RunState { id = id, status = Active, cancel_requested = false,
          steps = map(\(definition) -> new_step(sim.now, definition), workflow.steps) }
        Ok(Simulator { ..sim, runs = append(sim.runs, [run]) })
    Tick(checkpoint) =>
      if not(sim.up) then Err("PROCESS_DOWN") else tick(sim, workflow, checkpoint)
    Advance(by) =>
      if sim.now + by > time_limit() then Err("TIME_OVERFLOW")
      else Ok(Simulator { ..sim, now = sim.now + by })
    Observe => Ok(Simulator { ..sim, observations = append(sim.observations, [snapshot(sim)]) })
    Crash =>
      if not(sim.up) then Err("PROCESS_DOWN") else Ok(Simulator { ..sim, up = false })
    Restart =>
      if sim.up then Err("PROCESS_UP") else Ok(Simulator { ..sim, up = true })
    Cancel(id) =>
      if not(sim.up) then Err("PROCESS_DOWN")
      else
        match find(\(run) -> run.id == id, sim.runs) of
          None => Err("UNKNOWN_RUN")
          Some(run) =>
            if run.status == Completed || run.status == RunFailed || run.status == RunCancelled then Ok(sim)
            else
              let steps = map(cancel_pending, run.steps)
              let has_running = any(\(step) -> step.status == Running, steps)
              let status = if has_running then Cancelling else RunCancelled
              Ok(replace_run(sim, RunState { ..run, status = status, cancel_requested = true, steps = steps }))

fn run_commands(sim : Simulator, workflow : Workflow, commands : List(Command)) : Result(Simulator, String) =
  match commands of
    Nil => Ok(sim)
    Cons(command, rest) =>
      let next = apply_command(sim, workflow, command)?
      run_commands(next, workflow, rest)

pub fn simulate(workflow : Workflow) : Result(Simulator, String) =
  run_commands(new_simulator(), workflow, workflow.commands)

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Domain (..)

pub fn new_service() : MockService = MockService { calls = [], effects = [] }

fn same_key(a : ActionKey, b : ActionKey) : Bool =
  a.run_id == b.run_id && a.step_id == b.step_id

fn effect_exists(service : MockService, key : ActionKey) : Bool =
  any(\(entry) -> same_key(entry.key, key), service.effects)

fn execute_count(calls : List(ServiceCall), key : ActionKey) : Int =
  foldl(\(n, call) -> if call.kind == "execute" && same_key(call.key, key) then n + 1 else n, 0, calls)

fn add_call(service : MockService, kind : String, key : ActionKey, attempt : Int, outcome : String) : MockService =
  MockService { ..service, calls = append(service.calls,
    [ServiceCall { kind = kind, key = key, attempt = attempt, outcome = outcome }]) }

pub fn execute(service : MockService, key : ActionKey, amount : Int, attempt : Int, failures : Int) : ServiceResult =
  if effect_exists(service, key) then
    ServiceResult { service = add_call(service, "execute", key, attempt, "replayed"), outcome = "replayed" }
  elif execute_count(service.calls, key) < failures then
    ServiceResult { service = add_call(service, "execute", key, attempt, "transient"), outcome = "transient" }
  else
    let effected = MockService { ..service, effects = append(service.effects, [Effect { key = key, amount = amount }]) }
    ServiceResult { service = add_call(effected, "execute", key, attempt, "applied"), outcome = "applied" }

pub fn lookup(service : MockService, key : ActionKey, attempt : Int) : ServiceResult =
  let outcome = if effect_exists(service, key) then "found" else "missing"
  ServiceResult { service = add_call(service, "lookup", key, attempt, outcome), outcome = outcome }

import Data.List (..)
import Data.Foldable (..)
import Data.String (..)
import Data.Result (..)
import Json (..)
import Domain (..)
import Validation (..)
import Runner (simulate)
import Output (response_json)

fn handle_request(line : String) : Result(Simulator, String) =
  let request = map_err(\(_) -> "INVALID_INPUT", decode_lossy(line))?
  let workflow = parse_request(request)?
  simulate(workflow)

fn main() = println(encode(response_json(handle_request(read_line()))))

